function createUI(dependencies) {
  const h = dependencies.h;
  const React = dependencies.React;
  const { useEffect, useRef } = React;

  function Icon(props) {
    const name = props.name || 'info';
    const size = props.size || 16;
    const nodes = ICON_NODES[name] || ICON_NODES.info;
    return h(
      'svg',
      {
        width: size,
        height: size,
        viewBox: '0 0 24 24',
        fill: 'none',
        stroke: 'currentColor',
        strokeWidth: 1.7,
        strokeLinecap: 'round',
        strokeLinejoin: 'round',
        'aria-hidden': 'true',
        className: cx('hi-icon', props.className),
      },
      nodes.map((node, index) => {
        const { tag, ...attributes } = node;
        return h(tag, { key: index, ...attributes });
      }),
    );
  }

  function IconButton(props) {
    return h(
      'button',
      {
        type: 'button',
        className: cx('hi-iconbtn', props.className),
        title: props.label,
        'aria-label': props.label,
        disabled: props.disabled,
        style: props.style,
        onClick: props.onClick,
      },
      h(Icon, { name: props.icon, size: props.size || 16 }),
    );
  }

  function Button(props) {
    const className = cx(
      'hi-btn',
      `hi-btn-${props.variant || 'secondary'}`,
      props.size === 'sm' ? 'hi-btn-sm' : '',
      props.className,
    );
    return h(
      'button',
      {
        type: props.type || 'button',
        className,
        disabled: props.disabled,
        title: props.title,
        style: props.style,
        onClick: props.onClick,
      },
      props.icon ? h(Icon, { name: props.icon, size: props.size === 'sm' ? 14 : 15 }) : null,
      props.children,
    );
  }

  function Field(props) {
    return h(
      'label',
      { className: cx('hi-field', props.className), style: props.style },
      h(
        'span',
        { className: 'hi-field-label' },
        props.label,
        props.required ? h('span', { className: 'hi-required' }, '*') : null,
      ),
      props.children,
      props.hint ? h('span', { className: 'hi-field-hint' }, props.hint) : null,
    );
  }

  function Spinner(props) {
    return h(
      'span',
      { className: cx('hi-loading', props.className), role: 'status' },
      h('span', { className: 'hi-spinner', 'aria-hidden': 'true' }),
      props.label || null,
    );
  }

  function Badge(props) {
    return h('span', { className: cx('hi-badge', props.tone ? `hi-badge-${props.tone}` : '', props.className) }, props.children);
  }

  function ProgressBar(props) {
    const value = clamp(Number(props.value) || 0, 0, 1);
    return h(
      'div',
      { className: cx('hi-progress-wrap', props.className), role: 'progressbar', 'aria-valuenow': Math.round(value * 100), 'aria-valuemin': 0, 'aria-valuemax': 100 },
      h('div', { className: 'hi-progress' }, h('span', { className: 'hi-progress-fill', style: { width: `${value * 100}%` } })),
    );
  }

  function EmptyState(props) {
    return h(
      'div',
      { className: cx('hi-empty', props.className) },
      h('span', { className: 'hi-empty-icon' }, h(Icon, { name: props.icon || 'spark', size: 22 })),
      h('h3', null, props.title),
      props.body ? h('p', null, props.body) : null,
      props.action || null,
    );
  }

  function Modal(props) {
    const boxRef = useRef(null);
    useEffect(() => {
      const onKeyDown = (event) => {
        if (event.key === 'Escape' && props.onClose && props.dismissible !== false) props.onClose();
      };
      window.addEventListener('keydown', onKeyDown);
      const target = boxRef.current;
      if (target) {
        const focusable = target.querySelector('input, textarea, select, button');
        if (focusable && typeof focusable.focus === 'function') focusable.focus();
      }
      return () => window.removeEventListener('keydown', onKeyDown);
    }, [props.onClose, props.dismissible]);
    return h(
      'div',
      {
        className: 'hi-modal-backdrop',
        onMouseDown: (event) => {
          if (event.target === event.currentTarget && props.dismissible !== false && props.onClose) props.onClose();
        },
      },
      h(
        'div',
        {
          ref: boxRef,
          className: cx('hi-modal', props.className),
          role: 'dialog',
          'aria-modal': 'true',
          'aria-label': props.title,
          style: props.width ? { maxWidth: props.width } : undefined,
        },
        h(
          'header',
          { className: 'hi-modal-head' },
          h(
            'div',
            null,
            h('h2', null, props.title),
            props.subtitle ? h('p', null, props.subtitle) : null,
          ),
          h(IconButton, {
            icon: 'close',
            label: props.closeLabel || 'Close',
            onClick: props.onClose,
            disabled: props.dismissible === false,
          }),
        ),
        h('div', { className: 'hi-modal-body' }, props.children),
        props.footer ? h('footer', { className: 'hi-modal-foot' }, props.footer) : null,
      ),
    );
  }

  return { Icon, IconButton, Button, Field, Spinner, Badge, ProgressBar, EmptyState, Modal };
}

// ── client/core/annotation-api.js ──
/**
 * Browser-side annotation API.
 *
 * This is the only browser module allowed to call `fetch` for annotation data.
 * The UI and annotation app talk to this facade; a task-scoped facade obtained
 * from `forTask(taskId)` exposes exactly the read/status/result operations an
 * annotation app needs. Dataset mutation is exposed separately under
 * `AnnotationApi.datasets`, so an annotation app cannot change its dataset.
 */
const AnnotationApi = (() => {
  const BASE = '/human-intelligence/api';

  async function request(pathname, options) {
    const settings = options || {};
    const init = {
      method: settings.method || 'GET',
      credentials: 'same-origin',
      cache: 'no-store',
      signal: settings.signal,
    };
    if (settings.body !== undefined) {
      init.headers = { 'content-type': 'application/json' };
      init.body = JSON.stringify(settings.body);
    }
    let response;
    try {
      response = await fetch(`${BASE}${pathname}`, init);
    } catch (error) {
      if (error && error.name === 'AbortError') throw error;
      throw new Error('NETWORK');
    }
    const payload = await response.json().catch(() => null);
    if (!response.ok) {
      const message =
        payload && payload.error && typeof payload.error.message === 'string'
          ? payload.error.message
          : `HTTP ${response.status}`;
      const failure = new Error(message);
      failure.status = response.status;
      throw failure;
    }
    return payload;
  }

  async function upload(file) {
    let response;
    try {
      response = await fetch(`${BASE}/media?name=${encodeURIComponent(file.name || 'upload')}`, {
        method: 'POST',
        credentials: 'same-origin',
        cache: 'no-store',
        headers: { 'content-type': file.type || 'application/octet-stream' },
        body: file,
      });
    } catch {
      throw new Error('NETWORK');
    }
    const payload = await response.json().catch(() => null);
    if (!response.ok) {
      const message =
        payload && payload.error && typeof payload.error.message === 'string'
          ? payload.error.message
          : `HTTP ${response.status}`;
      throw new Error(message);
    }
    return payload.media;
  }

  const tasks = {
    list() {
      return request('/state').then((state) => state.tasks);
    },
    create(input) {
      return request('/tasks', { method: 'POST', body: input });
    },
    get(taskId) {
      return request(`/tasks/${encodeURIComponent(taskId)}`);
    },
    update(taskId, patch) {
      return request(`/tasks/${encodeURIComponent(taskId)}`, { method: 'PATCH', body: patch });
    },
    remove(taskId) {
      return request(`/tasks/${encodeURIComponent(taskId)}`, { method: 'DELETE' });
    },
    exportUrl(taskId) {
      return `${BASE}/tasks/${encodeURIComponent(taskId)}/export`;
    },
  };

  const datasets = {
    list() {
      return request('/datasets').then((payload) => payload.datasets);
    },
    create(input) {
      return request('/datasets', { method: 'POST', body: input });
    },
    get(datasetId) {
      return request(`/datasets/${encodeURIComponent(datasetId)}`);
    },
    update(datasetId, patch) {
      return request(`/datasets/${encodeURIComponent(datasetId)}`, { method: 'PATCH', body: patch });
    },
    remove(datasetId) {
      return request(`/datasets/${encodeURIComponent(datasetId)}`, { method: 'DELETE' });
    },
    addItems(datasetId, items) {
      return request(`/datasets/${encodeURIComponent(datasetId)}/items`, {
        method: 'POST',
        body: { items },
      });
    },
    removeItem(datasetId, itemId) {
      return request(
        `/datasets/${encodeURIComponent(datasetId)}/items/${encodeURIComponent(itemId)}`,
        { method: 'DELETE' },
      );
    },
  };

  const annotations = {
    save(taskId, itemId, input) {
      return request(
        `/tasks/${encodeURIComponent(taskId)}/dataset/items/${encodeURIComponent(itemId)}/annotation`,
        { method: 'PUT', body: input },
      );
    },
    setStatus(taskId, itemId, status) {
      return request(
        `/tasks/${encodeURIComponent(taskId)}/dataset/items/${encodeURIComponent(itemId)}/status`,
        { method: 'PATCH', body: { status } },
      );
    },
  };

  const tools = {
    list() {
      return request('/tools').then((payload) => payload.tools);
    },
    create(input) {
      return request('/tools', { method: 'POST', body: input });
    },
    remove(toolId) {
      return request(`/tools/${encodeURIComponent(toolId)}`, { method: 'DELETE' });
    },
  };

  const media = {
    upload,
    url(file) {
      return `${BASE}/media/${encodeURIComponent(file)}`;
    },
  };

  function state() {
    return request('/state');
  }

  function forTask(taskId) {
    return {
      taskId,
      get: () => tasks.get(taskId),
      getDataset: () => tasks.get(taskId).then((detail) => detail.dataset),
      saveAnnotation: (itemId, value, status) => annotations.save(taskId, itemId, { value, status }),
      setStatus: (itemId, status) => annotations.setStatus(taskId, itemId, status),
      exportUrl: () => tasks.exportUrl(taskId),
    };
  }

  return { state, tasks, datasets, annotations, tools, media, forTask };
})();

// ── client/core/file-importer.js ──
/* Shared upload importer used by the image and video modality modules. */
function createFileItemImporter(options) {
  const h = options.h;
  const React = options.React;
  const ui = options.ui;
  const kind = options.kind;
  const accept = options.accept;
  const typesLabel = options.typesLabel;
  const sizeLabel = options.sizeLabel;
  const icon = options.icon || (kind === 'video' ? 'video' : 'image');
  const maxBytes = options.maxBytes || 512 * 1024 * 1024;

  return function FileItemImporter(props) {
    const t = props.t;
    const [files, setFiles] = React.useState([]);
    const [busy, setBusy] = React.useState(false);
    const [progress, setProgress] = React.useState('');
    const [error, setError] = React.useState('');
    const inputRef = React.useRef(null);

    function addFiles(list) {
      const incoming = Array.from(list || []);
      if (incoming.length === 0) return;
      setFiles((current) => {
        const merged = current.slice();
        for (const file of incoming) {
          if (!merged.some((entry) => entry.name === file.name && entry.size === file.size && entry.lastModified === file.lastModified)) {
            merged.push(file);
          }
        }
        return merged;
      });
      setError('');
    }

    function onDrop(event) {
      event.preventDefault();
      if (busy) return;
      addFiles(event.dataTransfer && event.dataTransfer.files);
    }

    async function submit() {
      if (files.length === 0) {
        setError(t('importer.file.none'));
        return;
      }
      setBusy(true);
      setError('');
      try {
        const items = [];
        for (const file of files) {
          if (!file.type || !file.type.startsWith(`${kind}/`)) {
            throw new Error(t('importer.file.unsupported', { name: file.name }));
          }
          if (file.size > maxBytes) {
            throw new Error(t('importer.file.tooLarge', { name: file.name, size: sizeLabel }));
          }
          setProgress(t('importer.file.uploading', { name: file.name }));
          const media = await AnnotationApi.media.upload(file);
          items.push({ name: file.name, media });
        }
        await props.onAdd(items);
      } catch (failure) {
        setError(
          failure && failure.message === 'NETWORK'
            ? t('common.networkError')
            : failure && failure.message
              ? failure.message
              : t('common.networkError'),
        );
      } finally {
        setBusy(false);
        setProgress('');
      }
    }

    return h(
      'div',
      { className: 'hi-form' },
      h('p', { className: 'hi-task-note' }, t('importer.file.hint', { types: typesLabel, size: sizeLabel })),
      h(
        'div',
        {
          className: 'hi-file-drop',
          onDragOver: (event) => event.preventDefault(),
          onDrop,
        },
        h(ui.Icon, { name: icon, size: 26 }),
        h('strong', null, t('importer.file.choose')),
        h('span', null, `${typesLabel} · ${sizeLabel}`),
        h(
          ui.Button,
          { variant: 'secondary', icon: 'plus', disabled: busy, onClick: () => inputRef.current && inputRef.current.click() },
          t('importer.file.browse'),
        ),
        h('input', {
          ref: inputRef,
          type: 'file',
          multiple: true,
          accept,
          style: { display: 'none' },
          onChange: (event) => {
            addFiles(event.target.files);
            event.target.value = '';
          },
        }),
      ),
      files.length > 0
        ? h(
            'div',
            { className: 'hi-file-list' },
            files.map((file) =>
              h(
                'div',
                { key: `${file.name}:${file.size}:${file.lastModified}`, className: 'hi-file-row' },
                h('span', null, file.name),
                h('span', null, formatBytes(file.size)),
                h(
                  ui.IconButton,
                  {
                    icon: 'close',
                    label: t('common.cancel'),
                    disabled: busy,
                    onClick: () => setFiles((current) => current.filter((entry) => entry !== file)),
                  },
                ),
              ),
            ),
          )
        : null,
      progress ? h('div', { className: 'hi-file-row' }, h(ui.Spinner, { label: progress })) : null,
      h(
        'div',
        { className: 'hi-modal-foot', style: { padding: 0, border: 0, background: 'transparent' } },
        h(
          'span',
          { className: 'hi-toolbar-count', style: { marginRight: 'auto' } },
          files.length > 0 ? `${files.length} ${t('importer.file.files')}` : t('importer.file.none'),
        ),
        h(
          ui.Button,
          { variant: 'primary', icon: 'plus', disabled: busy || files.length === 0, onClick: () => void submit() },
          busy ? t('common.loading') : t('importer.file.submit', { n: files.length }),
        ),
      ),
      error
        ? h('div', { className: 'hi-form-error' }, h(ui.Icon, { name: 'alert', size: 14 }), h('span', null, error))
        : null,
    );
  };
}

// ── client/core/registry.js ──
/**
 * Modality and task registry.
 *
 * A modality module owns one data kind (text, image, video) and composes the
 * task modules it supports. A task module owns its annotation value shape, its
 * editor, its validation, its summary and its option form fields. The registry
 * is the only place that knows the list of modules; the workbench only talks to
 * this interface.
 */
function createRegistry(options) {
  const h = options.h;
  const React = options.React;
  const ui = options.ui;
  const entries = Array.isArray(options.modalityFactories) ? options.modalityFactories : [];

  const modalityList = [];
  const modalityIds = new Set();
  const taskIds = new Set();
  const taskLookup = new Map();

  for (const entry of entries) {
    const descriptor = entry.factory({ h, React, ui, taskFactories: entry.tasks || [] });
    if (!descriptor || typeof descriptor.id !== 'string' || descriptor.id === '') {
      throw new Error('A modality module must declare a non-empty id.');
    }
    if (modalityIds.has(descriptor.id)) throw new Error(`Duplicate modality id: ${descriptor.id}`);
    modalityIds.add(descriptor.id);
    const tasks = Array.isArray(descriptor.tasks) ? descriptor.tasks : [];
    for (const task of tasks) {
      if (!task || typeof task.id !== 'string' || task.id === '') {
        throw new Error(`Modality ${descriptor.id} declared a task without an id.`);
      }
      if (taskIds.has(task.id)) throw new Error(`Duplicate task id: ${task.id}`);
      if (task.modality !== descriptor.id) {
        throw new Error(`Task ${task.id} declares modality ${task.modality} inside ${descriptor.id}.`);
      }
      if (typeof task.Editor !== 'function') throw new Error(`Task ${task.id} must provide an Editor component.`);
      if (typeof task.initial !== 'function') throw new Error(`Task ${task.id} must provide initial().`);
      taskIds.add(task.id);
      taskLookup.set(`${descriptor.id}:${task.id}`, task);
    }
    modalityList.push(descriptor);
  }

  function modalityOf(id) {
    return modalityList.find((descriptor) => descriptor.id === id) || null;
  }

  function taskOf(modalityId, taskId) {
    return taskLookup.get(`${modalityId}:${taskId}`) || null;
  }

  function allTasks() {
    return modalityList.flatMap((descriptor) => descriptor.tasks.map((task) => ({ modality: descriptor, task })));
  }

  function defaultTaskOptions(task) {
    const output = {};
    const fields = Array.isArray(task.options) ? task.options : [];
    for (const field of fields) {
      if (!field || typeof field.key !== 'string') continue;
      if (Array.isArray(field.default)) output[field.key] = [...field.default];
      else if (field.default !== undefined) output[field.key] = field.default;
      else if (field.kind === 'tags') output[field.key] = [];
      else output[field.key] = '';
    }
    return output;
  }

  function resolveOptions(task, taskOptions) {
    const merged = { ...defaultTaskOptions(task), ...(taskOptions && typeof taskOptions === 'object' ? taskOptions : {}) };
    return merged;
  }

  function describe(descriptor) {
    return descriptor;
  }

  function messages() {
    const merged = { zh: {}, en: {} };
    const collect = (owner) => {
      const dictionaries = owner && owner.messages;
      if (!dictionaries || typeof dictionaries !== 'object') return;
      for (const language of Object.keys(dictionaries)) {
        merged[language] = merged[language] || {};
        Object.assign(merged[language], dictionaries[language] || {});
      }
    };
    for (const descriptor of modalityList) {
      collect(descriptor);
      for (const task of descriptor.tasks) collect(task);
    }
    return merged;
  }

  function styles() {
    const output = [];
    for (const descriptor of modalityList) {
      if (typeof descriptor.styles === 'string') output.push(descriptor.styles);
      for (const task of descriptor.tasks) if (typeof task.styles === 'string') output.push(task.styles);
    }
    return output;
  }

  return {
    modalities: modalityList,
    modalityOf,
    taskOf,
    allTasks,
    defaultTaskOptions,
    resolveOptions,
    describe,
    messages,
    styles,
  };
}

